import csv
import io
import re

def parse_csv(raw_csv: str):
    text = raw_csv if isinstance(raw_csv, str) else str(raw_csv)
    if text.startswith("\ufeff"):
        text = text[1:]

    try:
        csv.field_size_limit(2147483647)
    except (OverflowError, csv.Error):
        pass

    reader = csv.reader(
        io.StringIO(text, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = [list(row) for row in reader]

    def is_blank(row):
        return not row or all(value.strip() == "" for value in row)

    def normalize(value):
        return re.sub(r"[^a-z0-9]+", "", value.lower().lstrip("\ufeff"))

    expected_width = 9
    header_terms = {
        "date",
        "time",
        "qty",
        "quantity",
        "productid",
        "price",
        "producttype",
        "productdescription",
        "url",
        "comments",
        "comment",
    }

    header_index = None
    best_score = -1

    for index, row in enumerate(records[:100]):
        if is_blank(row):
            continue
        normalized = [normalize(value) for value in row]
        matches = sum(1 for value in normalized if value in header_terms)
        unique_matches = len(set(normalized) & header_terms)
        score = matches * 3 + unique_matches
        if len(row) == expected_width:
            score += 4
        if "date" in normalized and "time" in normalized:
            score += 5
        if "productid" in normalized:
            score += 5
        if score > best_score:
            best_score = score
            header_index = index

    if header_index is None or best_score < 8:
        header_index = None
        for index, row in enumerate(records):
            if not is_blank(row) and len(row) == expected_width:
                header_index = index
                break
        if header_index is None:
            for index, row in enumerate(records):
                if not is_blank(row):
                    header_index = index
                    break

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    if len(columns) < expected_width:
        columns.extend("" for _ in range(expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [
            ",".join(columns[expected_width - 1:])
        ]

    normalized_columns = [normalize(value) for value in columns]

    def column_index(*names):
        for name in names:
            if name in normalized_columns:
                return normalized_columns.index(name)
        return None

    description_index = column_index("productdescription", "description")
    url_index = column_index("url", "link", "website")
    comments_index = column_index("comments", "comment", "notes")

    if description_index is None:
        description_index = max(0, expected_width - 3)
    if url_index is None:
        url_index = max(description_index + 1, expected_width - 2)
    if comments_index is None:
        comments_index = expected_width - 1

    url_pattern = re.compile(r"^\s*[a-zA-Z][a-zA-Z0-9+.-]*:(?://)?")

    def find_url(row):
        for index, value in enumerate(row):
            if url_pattern.match(value):
                return index
        return None

    def repair_row(row):
        row = list(row)

        if len(row) == expected_width:
            return row

        located_url = find_url(row)

        if len(row) < expected_width:
            if located_url is not None and located_url < url_index:
                missing = min(expected_width - len(row), url_index - located_url)
                row[located_url:located_url] = [""] * missing
            if len(row) < expected_width:
                row.extend("" for _ in range(expected_width - len(row)))
            return row[:expected_width]

        if (
            located_url is not None
            and description_index < url_index
            and located_url >= description_index
        ):
            result = row[:description_index]
            description_parts = row[description_index:located_url]
            result.append(",".join(description_parts))
            while len(result) < url_index:
                result.append("")
            result.append(row[located_url])

            trailing = row[located_url + 1:]
            while len(result) < comments_index:
                if trailing:
                    result.append(trailing.pop(0))
                else:
                    result.append("")

            if len(result) == comments_index:
                result.append(",".join(trailing) if trailing else "")
            elif trailing:
                result[-1] = result[-1] + (
                    "," if result[-1] and trailing else ""
                ) + ",".join(trailing)

            if len(result) < expected_width:
                result.extend("" for _ in range(expected_width - len(result)))
            elif len(result) > expected_width:
                result = result[:expected_width - 1] + [
                    ",".join(result[expected_width - 1:])
                ]
            return result

        excess = len(row) - expected_width
        merge_index = min(max(description_index, 0), expected_width - 1)
        merged = (
            row[:merge_index]
            + [",".join(row[merge_index:merge_index + excess + 1])]
            + row[merge_index + excess + 1:]
        )
        if len(merged) < expected_width:
            merged.extend("" for _ in range(expected_width - len(merged)))
        elif len(merged) > expected_width:
            merged = merged[:expected_width - 1] + [
                ",".join(merged[expected_width - 1:])
            ]
        return merged

    rows = []
    for row in records[header_index + 1:]:
        if is_blank(row):
            continue
        rows.append(repair_row(row))

    return {"columns": columns, "rows": rows}
